      "missing_details_ko": ""
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "target_relation": "different",
      "reference_claim_ids": [
        "R1.S3"
      ],
      "reference_evidence": "the camera zooms too quickly",
      "candidate_evidence": "The prominent central leaf vein abruptly disappears and reappears as the camera zooms/blurs.",
      "basis": "explicit_separation",
      "reason_ko": "R1.S3는 카메라의 줌 속도가 너무 빠르다는 카메라 움직임의 결함을 기술하는 반면, C2는 잎맥이 사라졌다가 다시 나타나는 식물 세부 구조의 깜빡임/소실 결함을 지목하고 있어 서로 구분되는 별개의 결함 현상입니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "target_relation": "different",
      "reference_claim_ids": [
        "R1.S2"
      ],
      "reference_evidence": "The plant’s color shifts slightly",
      "candidate_evidence": "The central leaf and background plant foliage exhibit warping, unnatural blurring, and morphing during the rapid zoom-in and zoom-out transitions.",
      "basis": "explicit_separation",
      "reason_ko": "R1.S2는 식물의 색상 변화(color shifts)를 구체적으로 다루는 반면, C3는 잎과 배경 식물의 형태적 왜곡(warping, morphing) 및 부자연스러운 블러 현상을 기술하므로 두 텍스트는 명확히 구별되는 결함을 서술하고 있습니다."
    }
  ]
}

